  "53": { es: "Downhill Bike Tour: del Teide al mar sin pedalear. 35 km por carreteras. Picnic y cava incluidos. Desde 1999.", de: "Downhill Bike Tour: vom Teide ans Meer ohne zu treten. 35 km auf asphaltierten Straßen. Picknick und Cava inklusive.", fr: "Tour vélo descente: du Teide à la mer sans pédaler. 35 km. Pique-nique et cava inclus. Depuis 1999.", it: "Tour in bicicletta in discesa: dal Teide al mare senza pedalare. 35 km. Picnic e cava inclusi.", ru: "Велотур: от Тейде до моря без педалирования. 35 км по асфальту. Пикник и кава включены. С 1999.", pl: "Wycieczka rowerowa w dół: od Teide do morza bez pedałowania. 35 km. Piknik i cava wliczone." },
  "55": { es: "Jeep Safari Teide medio día: Parque Nacional, Roques de García, Pico Viejo. Ideal para familias. Recogida en alojamiento.", de: "Jeep Safari Teide halber Tag: Nationalpark, Roques de García, Pico Viejo. Ideal für Familien. Abholung inklusive.", fr: "Jeep Safari Teide demi-journée: parc national, Roques de García, Pico Viejo. Idéal familles. Prise en charge.", it: "Jeep Safari Teide mezza giornata: parco nazionale, Roques de García, Pico Viejo. Ideale per famiglie. Ritiro incluso.", ru: "Jeep Safari Тейде полдня: национальный парк, Рокес-де-Гарсия, Пико-Вьехо. Для семей. Трансфер включён.", pl: "Jeep Safari Teide pół dnia: park narodowy, Roques de García, Pico Viejo. Dla rodzin. Odbiór wliczony." },
  "58": { es: "Banana Boat y Flying Fish: adrenalina en el agua. Banana 5 m tirada por lancha. Fly Fish: deslizamiento sobre las olas. 10 min de diversión.", de: "Banana Boat und Flying Fish: Adrenalin auf dem Wasser. 5 m Banane vom Speedboot gezogen. 10 Min Spaß.", fr: "Banana Boat et Flying Fish: adrénaline sur l'eau. Banane 5 m tractée. 10 min de plaisir.", it: "Banana Boat e Flying Fish: adrenalina sull'acqua. Banana 5 m trainata. 10 min di divertimento.", ru: "Banana Boat и Flying Fish: адреналин на воде. 5 м банан за катером. 10 мин веселья.", pl: "Banana Boat i Flying Fish: adrenalina na wodzie. 5 m banan ciągnięty przez motorówkę. 10 min zabawy." },
  "67": { es: "Pirámides de Güímar: parque etnográfico y jardín botánico. Fundado por Thor Heyerdahl en 1998. 64.000 m², jardín de venenos, rutas volcánicas.", de: "Pyramiden von Güímar: ethnographischer Park und Botanischer Garten. Gegründet 1998 von Thor Heyerdahl. Gartengiftgarten.", fr: "Pyramides de Güímar: parc ethnographique et jardin botanique. Fondé par Thor Heyerdahl 1998. Jardin des poisons.", it: "Piramidi di Güímar: parco etnografico e orto botanico. Fondato da Thor Heyerdahl 1998. Giardino dei veleni.", ru: "Пирамиды Гуимар: этнографический парк и ботанический сад. Основан Тором Хейердалом 1998. Сад ядовитых растений.", pl: "Piramidy Güímar: park etnograficzny i ogród botaniczny. Założony przez Thora Heyerdahla 1998. Ogród trucizn." },
  "70": { es: "Shogun: velero oriental de teca. 5h de excursión, avistamiento de ballenas y delfines, baño en la bahía de Masca, almuerzo a bordo.", de: "Shogun: orientalisches Teakholz-Segelboot. 5h Tour, Wal- und Delfinbeobachtung, Bad in der Bucht von Masca, Mittagessen an Bord.", fr: "Shogun: voilier oriental en teck. 5h, observation baleines et dauphins, baignade à Masca, déjeuner à bord.", it: "Shogun: veliero orientale in teak. 5h, avvistamento balene e delfini, bagno nella baia di Masca, pranzo a bordo.", ru: "Shogun: восточная яхта из тика. 5ч, киты и дельфины, купание в бухте Маска, обед на борту.", pl: "Shogun: orientalny żaglowiec z teaku. 5h, obserwacja waleni i delfinów, kąpiel w zatoce Masca, obiad na pokładzie." },
  "72": { es: "Flipper Uno: desde Los Gigantes, búsqueda de ballenas y delfines. Acantilados de Masca y Los Gigantes. Bebidas y guía incluidos.", de: "Flipper Uno: ab Los Gigantes, Wal- und Delfinsuche. Klippen von Masca und Los Gigantes. Getränke und Guide inklusive.", fr: "Flipper Uno: départ Los Gigantes, recherche baleines et dauphins. Falaises de Masca. Boissons et guide inclus.", it: "Flipper Uno: da Los Gigantes, ricerca balene e delfini. Scogliere di Masca e Los Gigantes. Bevande e guida incluse.", ru: "Flipper Uno: из Лос-Гигантес, поиск китов и дельфинов. Скалы Маска и Лос-Гигантес. Напитки и гид включены.", pl: "Flipper Uno: z Los Gigantes, szukanie waleni i delfinów. Klify Masca i Los Gigantes. Napoje i przewodnik wliczone." },
  "78": { es: "Santa Cruz, Anaga y La Laguna: capital, macizo de Anaga (reserva biosfera UNESCO), La Laguna (patrimonio mundial). Tres joyas del norte.", de: "Santa Cruz, Anaga und La Laguna: Hauptstadt, Anaga-Massiv (UNESCO-Biosphärenreservat), La Laguna (Weltkulturerbe). Drei Juwelen des Nordens.", fr: "Santa Cruz, Anaga et La Laguna: capitale, massif d'Anaga (réserve UNESCO), La Laguna (patrimoine mondial). Trois perles du nord.", it: "Santa Cruz, Anaga e La Laguna: capitale, massiccio Anaga (riserva UNESCO), La Laguna (patrimonio mondiale). Tre gioielli del nord.", ru: "Санта-Крус, Анага и Ла-Лагуна: столица, массив Анага (ЮНЕСКО), Ла-Лагуна (наследие). Три жемчужины севера.", pl: "Santa Cruz, Anaga i La Laguna: stolica, masyw Anaga (rezerwat UNESCO), La Laguna (dziedzictwo). Trzy perły północy." },
  "90": { es: "Fly Fish: desafía las leyes de la física. Vuelos impresionantes a alta velocidad. ¿Te atreves?", de: "Fly Fish: trotzt den Gesetzen der Physik. Beeindruckende Hochgeschwindigkeitsflüge. Wagst du es?", fr: "Fly Fish: défie les lois de la physique. Vols impressionnants à grande vitesse. Oserez-vous?", it: "Fly Fish: sfida le leggi della fisica. Voli spettacolari ad alta velocità. Ti azzardi?", ru: "Fly Fish: вызов законам физики. Потрясающие полёты на скорости. Осмелишься?", pl: "Fly Fish: wyzwanie dla praw fizyki. Niesamowite loty z prędkością. Odważysz się?" },
  "92": { es: "Top Buggy Adventure: descubre Tenerife en buggy. Paisajes volcánicos, rutas guiadas, fotógrafo profesional. Ideal para familias y parejas.", de: "Top Buggy Adventure: Entdecke Teneriffa im Buggy. Vulkanlandschaften, geführte Touren, professioneller Fotograf. Ideal für Familien.", fr: "Top Buggy Adventure: découvrez Tenerife en buggy. Paysages volcaniques, circuits guidés, photographe pro. Idéal familles.", it: "Top Buggy Adventure: scopri Tenerife in buggy. Paesaggi vulcanici, tour guidati, fotografo. Ideale per famiglie.", ru: "Top Buggy Adventure: открой Тенерифе на багги. Вулканические пейзажи, гиды, фотограф. Для семей.", pl: "Top Buggy Adventure: odkryj Teneryfę buggy. Krajobraz wulkaniczny, wycieczki z przewodnikiem, fotograf. Dla rodzin." },
  "97": { es: "Atardecer y estrellas en Teide: teleférico a 3.555 m, atardecer espectacular, cena picnic, observación con telescopios Starlight.", de: "Sonnenuntergang und Sterne auf dem Teide: Seilbahn auf 3.555 m, spektakulärer Sonnenuntergang, Picknick-Abendessen, Starlight-Teleskope.", fr: "Coucher de soleil et étoiles sur le Teide: téléphérique à 3.555 m, coucher spectaculaire, dîner pique-nique, télescopes Starlight.", it: "Tramonto e stelle sul Teide: funivia a 3.555 m, tramonto spettacolare, cena picnic, telescopi Starlight.", ru: "Закат и звёзды на Тейде: канатка до 3.555 м, закат, ужин-пикник, телескопы Starlight.", pl: "Zachód słońca i gwiazdy na Teide: kolejka na 3.555 m, spektakularny zachód, kolacja piknik, teleskopy Starlight." },
