  "131": { es: "Palmetum Santa Cruz: más de 2.000 especies de palmeras y plantas tropicales. Único jardín de montaña en la costa de la capital. Vistas al mar y Anaga.", de: "Palmetum Santa Cruz: über 2.000 Palmen- und Tropenpflanzenarten. Einziger Berggarten an der Küste der Hauptstadt. Blick auf Meer und Anaga.", fr: "Palmetum Santa Cruz: plus de 2.000 espèces de palmiers et plantes tropicales. Seul jardin de montagne sur la côte. Vues mer et Anaga.", it: "Palmetum Santa Cruz: oltre 2.000 specie di palme e piante tropicali. Unico giardino montano sulla costa. Vista mare e Anaga.", ru: "Palmetum Santa Cruz: более 2.000 видов пальм и тропических растений. Единственный горный сад на побережье. Вид на море и Анагу.", pl: "Palmetum Santa Cruz: ponad 2.000 gatunków palm i roślin tropikalnych. Jedyny ogród górski na wybrzeżu. Widok na morze i Anaga." },
  "134": { es: "Observatorio del Teide: el mayor observatorio solar del mundo. Visita guiada, telescopios solares y nocturnos. Altitud 2.390 m.", de: "Teide-Observatorium: weltweit größtes Sonnenobservatorium. Geführter Besuch, Sonnen- und Nachtteleskope. 2.390 m Höhe.", fr: "Observatoire du Teide: plus grand observatoire solaire du monde. Visite guidée, télescopes solaires et nocturnes. 2.390 m d'altitude.", it: "Osservatorio del Teide: il più grande osservatorio solare al mondo. Visita guidata, telescopi solari e notturni. 2.390 m di altitudine.", ru: "Обсерватория Тейде: крупнейшая солнечная обсерватория мира. Экскурсия, солнечные и ночные телескопы. 2.390 м.", pl: "Obserwatorium Teide: największe obserwatorium słoneczne na świecie. Zwiedzanie z przewodnikiem, teleskopy. 2.390 m n.p.m." },
  "137": { es: "Tour astronómico: observatorio del Teide, puesta de sol, cena y observación con telescopios de largo alcance. Guías Starlight.", de: "Astronomietour: Teide-Observatorium, Sonnenuntergang, Abendessen, Sternenbeobachtung mit Teleskopen. Starlight-Guides.", fr: "Tour astronomique: observatoire du Teide, coucher de soleil, dîner, observation aux télescopes. Guides Starlight.", it: "Tour astronomico: osservatorio Teide, tramonto, cena, osservazione con telescopi. Guide Starlight.", ru: "Астрономический тур: обсерватория Тейде, закат, ужин, наблюдение в телескопы. Гиды Starlight.", pl: "Wycieczka astronomiczna: obserwatorium Teide, zachód słońca, kolacja, obserwacja teleskopami. Przewodnicy Starlight." },
